# Run on 1 Kaggle GPU (or fix DEVICE="cpu" before launch). Requires the verified private PINNS input.
DEVICE="cuda"
from pathlib import Path
import base64, hashlib, os, subprocess, sys, time, urllib.request, zipfile, zlib

project_revision="66fb39d2de3df280ac831a4b5a0c0f095f1a0779"
repo=Path("/tmp/pinns_st_project_"+project_revision[:12])
subprocess.run(["git","init","-q",str(repo)],check=True)
subprocess.run(["git","-C",str(repo),"fetch","-q","--depth=1","https://github.com/pjyyyds/Unstructured-ShortPose-Pred.git",project_revision],check=True)
subprocess.run(["git","-C",str(repo),"checkout","--detach","-q",project_revision],check=True)
sys.path.insert(0,str(repo))
from scripts.stage_pinns_metadata import stage_metadata
data=stage_metadata(Path("/tmp/pinns_st_metadata"))
pose_sha="b493a47536664ddb4fd66603c1bbf6b2c2e33f553520382027b3ae96b53447d0"
pose=next((p for p in sorted(Path("/kaggle/input").rglob("pose.npz")) if hashlib.sha256(p.read_bytes()).hexdigest()==pose_sha),None)
if pose is None:
    candidates=[p for p in Path("/kaggle/input").rglob("shortpose_heldout_five_seeds.zip") if p.stat().st_size==42019120 and hashlib.sha256(p.read_bytes()).hexdigest()=="0bf2745ab2d5ddcf5f5fbb5d330e6c6cc800625cec301f4c7105d031bdb49d2d"]
    if not candidates: raise ValueError("Verified PINNS pose/cache input is missing")
    with zipfile.ZipFile(candidates[0]) as src: raw=src.read("pose.npz")
    if hashlib.sha256(raw).hexdigest()!=pose_sha: raise ValueError("Pose identity mismatch")
    pose=Path("/tmp/st_verified_pinns_pose.npz");pose.write_bytes(raw)
up=Path("/tmp/st_author_sources")
rev="7695ba335f7cba7f41660d0edc66a57cd52da08a"
for name,h in {"model_jrdb.py":"87ab7809431d943f1b94a62d92323641e2474d5030ca6569ef11888e08cc78f4","utils/metrics.py":"7b0f40c3b3ea1efca79815c75cc1fff2abce8d5567277d113c5026cba1ab0e63","LICENSE":"8486a10c4393cee1c25392769ddd3b2d6c242d6ec7928e1414efff7dfb2f07ef"}.items():
    dst=up/name;dst.parent.mkdir(parents=True,exist_ok=True)
    if dst.is_file() and hashlib.sha256(dst.read_bytes()).hexdigest()==h:continue
    for i in range(3):
        try:
            with urllib.request.urlopen("https://raw.githubusercontent.com/vita-epfl/social-transmotion/"+rev+"/"+name,timeout=30) as stream: raw=stream.read()
            if hashlib.sha256(raw).hexdigest()!=h:raise ValueError("Official source integrity check failed")
            dst.write_bytes(raw);break
        except (OSError,ValueError):
            if i==2:raise
            time.sleep(2**i)
code=Path("/tmp/st_pinns_locked_runner");code.mkdir(exist_ok=True)
def restore(name,h,encoded):
    raw=zlib.decompress(base64.b64decode(encoded))
    if hashlib.sha256(raw).hexdigest()!=h:raise ValueError("Changed "+name)
    (code/name).write_bytes(raw)
restore('run_pinns.py','19ed6716197b9703990ff94d23b630a67b2912c3abfd5cb0edf9cbabd981dfd6','')
restore('check_protocol.py','04fb90a642a6d318616f8cc4ca0a9972532bb51cbbe365cf87255d7d8fbde228','')
restore('THIRD_PARTY.md','b76fc766952368a0cbe7e8dc0ef1944f35e2257de5ba0bce865725beced5617a','')
restore('candidate_plan.json','623b492e71cc8ae62125331aafde017fcd1e64a9baebaaaa36781873e496f7ba','')
env={**os.environ,"PYTHONPATH":str(repo),"PYTHONHASHSEED":"42","CUBLAS_WORKSPACE_CONFIG":":4096:8","OMP_NUM_THREADS":"4","MKL_NUM_THREADS":"4","OPENBLAS_NUM_THREADS":"1"}
if DEVICE=="cpu":env["CUDA_VISIBLE_DEVICES"]=""
cmd=[sys.executable,"-u",str(code/"run_pinns.py"),str(data),str(pose),str(up),str(code/"candidate_plan.json"),"--device",DEVICE]
